<script setup>
// 家长管理中心：总览、孩子管理、任务、奖励、成长记录、账户设置
import {
  inAdmin, adminTab, students, tasks, rewards, logs, points, currentStudent,
  newTask, newReward
} from "../state.js";
import { backToStudent, logout, enterAdmin, switchStudent } from "../composables/useAuth.js";
import { addTask, addReward, deleteStudent, deleteTask, openAddStudent } from "../composables/useAdmin.js";
</script>

<template>
  <section v-if="inAdmin" class="admin card"><nav class="admin-nav"><button :class="{active:adminTab==='overview'}" @click="adminTab='overview'">总览</button><button :class="{active:adminTab==='students'}" @click="adminTab='students'">孩子管理</button><button :class="{active:adminTab==='tasks'}" @click="adminTab='tasks'">学习任务</button><button :class="{active:adminTab==='rewards'}" @click="adminTab='rewards'">奖励商店</button><button :class="{active:adminTab==='logs'}" @click="adminTab='logs'">成长记录</button><button :class="{active:adminTab==='settings'}" @click="adminTab='settings'">账户设置</button></nav><div class="admin-head"><div><p class="eyebrow orange">PARENT SPACE</p><h2>家长管理中心</h2></div><div><button class="back-link" @click="backToStudent">返回学习工作台</button><button class="danger-link" @click="logout">退出登录</button></div></div><div v-if="adminTab==='overview'" class="panel"><p class="muted">管理孩子的学习任务、奖励和成长记录。</p><div class="overview-grid"><div><b>{{ students.length }}</b><span>孩子账号</span></div><div><b>{{ tasks.filter(t=>t.status!=='done').length }}</b><span>待完成任务</span></div><div><b>{{ rewards.length }}</b><span>奖励项目</span></div><div><b>{{ points }}</b><span>当前积分</span></div></div><div class="admin-tip">💡 先添加孩子，再从学习工作台切换学习者；每个孩子的学习进度和积分独立保存。</div></div><div v-if="adminTab==='students'" class="panel"><h3>孩子账号</h3><p class="muted">创建后，孩子才能进入专属学习工作台。</p><button class="primary add-student-btn" @click="openAddStudent">＋ 添加孩子账号</button><div class="list"><div v-for="s in students" :key="s.id" class="list-row"><span class="avatar">{{ s.avatar || '🐣' }}</span><strong>{{ s.name }}</strong><small>{{ s.grade || 5 }}年级 · {{ s.username || '未设置用户名' }}</small><button class="select-link" @click="switchStudent(s.id)">{{ s.id === currentStudent ? '当前学习者' : '切换' }}</button><button class="danger-link" @click="deleteStudent(s.id)">删除</button></div><div v-if="!students.length" class="empty">还没有孩子账号，请先创建一个。</div></div></div><div v-if="adminTab==='tasks'" class="panel"><h3>学习任务</h3><div class="form-row"><input v-model="newTask.title" placeholder="任务名称，如：朗读课文" /><input v-model="newTask.due_date" type="date" /><input v-model.number="newTask.points" type="number" placeholder="奖励积分" /><button class="primary" @click="addTask">发布任务</button></div><div class="list"><div v-for="t in tasks" :key="t.id" class="list-row"><span class="task-check">✓</span><strong>{{ t.title }}</strong><small>+{{ t.points }} 积分 · {{ t.due_date || '今天' }}</small><button class="danger-link" @click="deleteTask(t.id)">删除</button></div><div v-if="!tasks.length" class="empty">还没有任务安排。</div></div></div><div v-if="adminTab==='rewards'" class="panel"><h3>奖励商店</h3><div class="form-row"><input v-model="newReward.name" placeholder="奖励名称，如：看一集动画片" /><input v-model.number="newReward.cost_points" type="number" placeholder="所需积分" /><button class="primary" @click="addReward">添加奖励</button></div><div class="reward-grid"><div v-for="r in rewards" :key="r.id" class="reward"><span class="reward-icon">◆</span><strong>{{ r.name }}</strong><b>{{ r.cost_points }} 积分</b></div><div v-if="!rewards.length" class="empty">还没有奖励项目。</div></div></div><div v-if="adminTab==='logs'" class="panel"><h3>成长记录</h3><div class="list"><div v-for="l in logs" :key="l.id" class="list-row"><span :class="l.delta > 0 ? 'gain' : 'loss'">{{ l.delta > 0 ? '+' : '' }}{{ l.delta }}</span><strong>{{ l.reason }}</strong><small>{{ l.created_at }}</small></div><div v-if="!logs.length" class="empty">完成学习后，这里会留下成长记录。</div></div></div><div v-if="adminTab==='settings'" class="panel"><h3>账户设置</h3><p class="muted">家长身份通过 Casdoor SSO 统一认证，每个家庭的孩子、任务与奖励数据互相独立。</p></div></section>
</template>
